import{_ as l,l as o,o as a,c as s,v as r,p as n,x as t,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"hrtimer","description":"","frontmatter":{"title":"hrtimer","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hrtimer.md","filePath":"cs/hrtimer.md","lastUpdated":1789023840000}'),m={name:"cs/hrtimer.md"};function p(_,e,f,u,E,B){const i=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="hrtimer" tabindex="-1">hrtimer <a class="header-anchor" href="#hrtimer" aria-label="Permalink to &quot;hrtimer&quot;">​</a></h1><div class="epigraph"><p>高精度定时器按绝对或相对纳秒期限排队；到期时靠时钟事件设备中断，而不是等下一个 HZ 滴答。</p><footer>—— 据 Gleixner 对 Linux hrtimer 的设计；POSIX clock_nanosleep 整理</footer></div><p><a href="/cs/jiffies">上一课</a>的粒度是毫秒级。<a href="/cs/realtime-sched">实时调度</a> 需要更紧的唤醒。<a href="/cs/io-uring">io_uring</a> 与 epoll 的超时若只对齐滴答，尾延迟差。缺口是 <strong>hrtimer</strong>：独立于 timer wheel 的期限队列，加上可编程的下一中断时刻。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提高 HZ 会增加中断负荷，仍是均匀滴答。无滴答内核在空闲时甚至关掉周期性 IRQ。缺口：把下一个最近期限编程进时钟事件设备；到期只跑那个回调；没有期限时可以睡到下一事件。软件侧用红黑树（或时间线）按到期排序。用户 <code>clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, …)</code> 走这条。</p><p>本课不把 clocksource 与 clockevent 的驱动列表背完。</p><p><span class="marginnote">slack 允许内核把期限稍微合并以省中断。实时任务可以要最小 slack。与 jiffies 定时器并存：粗的仍走 wheel，细的走 hrtimer。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注册 hrtimer：给定 ktime 与回调。内核计算最早期限，编程设备。IRQ：执行到期回调（可唤醒进程、推进网络重传等），再编程下一期限。回调不可长时间占 CPU，重活丢工作队列——对接已有下半部课。不要用 hrtimer 在回调里做阻塞 I/O。</p>',9)),(a(),n(d,null,{default:t(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DL%5B%22%E4%B8%8B%E4%B8%80%E6%9C%80%E6%97%A9%E6%9C%9F%E9%99%90%22%5D%20--%3E%20PROG%5B%22%E7%BC%96%E7%A8%8B%E6%97%B6%E9%92%9F%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20PROG%20--%3E%20IRQ%5B%22%E5%88%B0%E6%9C%9F%E4%B8%AD%E6%96%AD%22%5D%0A%20%20IRQ%20--%3E%20CB%5B%22%E5%9B%9E%E8%B0%83%22%5D%0A%20%20CB%20--%3E%20PROG%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>hrtimer 把时间从「节拍计数」升级为「事件驱动的期限」。调度器的高精度抢占、TCP 细超时、用户 nanosleep 共用。它不取代 jiffies 记账；CFS 仍可按纳秒差更新 vruntime，来源可以是同一 clocksource。与组成课的锁存器无关。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证在虚拟机里能得到主机级精度。不引入 timerfd 的全部接口，只承认期限可变成 fd 上的可读。下一课：字符设备上的人机接口——终端与伪终端，shell 与 SSH 都靠它。</p><p>后课默认：内核可按纳秒期限唤醒。字节流的终端行规程与 PTY，下一课 tty。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>hrtimer 按期限编程时钟事件，不绑死 HZ。</li><li>与 jiffies wheel 并存，服务 nanosleep 与实时唤醒。</li><li>终端作为进程的控制设备，是 tty 课的缺口。</li><li>出处：Gleixner, Linux hrtimer；POSIX clocks；Love, <em>LKD</em>。</li></ul>',7))])}const k=l(m,[["render",p]]);export{T as __pageData,k as default};
